574				// If the current path does not equal '/' and the node does not have a registered handle and the most recently matched node has a child node
575				// the current node needs to roll back to last vaild skippedNode
576				if n.handlers == nil && path != "/" {
577					for l := len(*skippedNodes); l > 0; {
578						skippedNode := (*skippedNodes)[l-1]
579						*skippedNodes = (*skippedNodes)[:l-1]
580						if strings.HasSuffix(skippedNode.path, path) {
581							path = skippedNode.path
582							n = skippedNode.node
583							if value.params != nil {
584								*value.params = (*value.params)[:skippedNode.paramsCount]
585							}
586							globalParamsCount = skippedNode.paramsCount
587							continue walk
588						}
589					}
590					//	n = latestNode.children[len(latestNode.children)-1]
591				}
592				// We should have reached the node containing the handle.
593				// Check if this node has a handle registered.
594				if value.handlers = n.handlers; value.handlers != nil {
595					value.fullPath = n.fullPath
596					return
597				}
598	
599				// If there is no handle for this route, but this route has a
600				// wildcard child, there must be a handle for this path with an
601				// additional trailing slash
602				if path == "/" && n.wildChild && n.nType != root {
603					value.tsr = true
604					return
605				}
606	
607				// No handle found. Check if a handle for this path + a
608				// trailing slash exists for trailing slash recommendation
609				for i, c := range []byte(n.indices) {
610					if c == '/' {
611						n = n.children[i]
612						value.tsr = (len(n.path) == 1 && n.handlers != nil) ||
613							(n.nType == catchAll && n.children[0].handlers != nil)
614						return
615					}
616				}
617	
618				return
619			}
