package gin

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

type tmpRoute struct {
	method string
	route  string
}

type tmpReq struct {
	method string
	path   string
	want   map[string]string
}

func runEngine(t *testing.T, name string, routes []tmpRoute, reqs []tmpReq) {
	t.Helper()
	func() {
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("[%s] PANIC while registering %v: %v", name, routes, r)
			}
		}()
		engine := New()
		var got Params
		var matched bool
		engine.Use(func(c *Context) {
			got = append(Params{}, c.Params...)
			matched = true
			c.Next()
		})
		for _, r := range routes {
			engine.Handle(r.method, r.route, func(c *Context) { c.String(200, "ok") })
		}
		for _, rq := range reqs {
			got = nil
			matched = false
			w := httptest.NewRecorder()
			req, _ := http.NewRequest(rq.method, rq.path, nil)
			engine.ServeHTTP(w, req)
			if !matched {
				t.Errorf("[%s] NOT MATCHED path=%q status=%d", name, rq.path, w.Code)
				continue
			}
			if len(rq.want) > 0 && len(got) == 0 {
				t.Errorf("[%s] EMPTY PARAMS path=%q -> %v (status %d)", name, rq.path, got, w.Code)
				continue
			}
			for k, v := range rq.want {
				gv, ok := got.Get(k)
				if !ok {
					t.Errorf("[%s] MISSING KEY path=%q want[%s]=%q got=%v", name, rq.path, k, v, got)
				} else if gv != v {
					t.Errorf("[%s] WRONG VALUE path=%q want[%s]=%q got=%q full=%v", name, rq.path, k, v, gv, got)
				}
			}
			if len(got) != len(rq.want) {
				t.Errorf("[%s] LEN MISMATCH path=%q want %d got %d: %v", name, rq.path, len(rq.want), len(got), got)
			}
		}
	}()
}

