import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func tmpNegotiate(t *testing.T, accept string, offers ...string) (res string, panicked any) {
	t.Helper()
	defer func() {
		if r := recover(); r != nil {
			panicked = r
		}
	}()
	w := httptest.NewRecorder()
	c, _ := CreateTestContext(w)
	req, _ := http.NewRequest(http.MethodGet, "/", nil)
	if accept != "" {
		req.Header.Set("Accept", accept)
	}
	c.Request = req
	res = c.NegotiateFormat(offers...)
	return
}

func TestZZTmpNegotiateProbe(t *testing.T) {
	accepts := []string{
		"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8",
		"*/*",
		"text/*",
		"application/json",
		"",
	}
	offerSets := [][]string{
		{MIMEJSON, MIMEXML},
		{MIMEXML, MIMEHTML},
		{MIMEJSON},
		{"text"},
		{"text/html"},
		{"application"},
		{"application/json; charset=utf-8"},
		{""},
		{MIMEHTML, MIMEJSON},
		{"text/plain", MIMEHTML},
	}
	for _, accept := range accepts {
		for _, offers := range offerSets {
			res, pan := tmpNegotiate(t, accept, offers...)
			if pan != nil {
				fmt.Printf("PANIC  accept=%-55q offers=%-45q -> panic: %v\n", accept, fmt.Sprint(offers), pan)
			} else {
				fmt.Printf("ok     accept=%-55q offers=%-45q -> %q\n", accept, fmt.Sprint(offers), res)
			}
		}
	}
}

