func zzBuild(t *testing.T, routes ...string) *node {
	t.Helper()
	tree := &node{}
	for _, r := range routes {
		func() {
			defer func() {
				if recv := recover(); recv != nil {
					t.Fatalf("panic inserting route %q: %v", r, recv)
