}

type zzCase struct {
	routes []string
	in     string
	out    string
	found  bool
	slash  bool
}

func zzRun(t *testing.T, cases []zzCase) {
	t.Helper()
	for _, c := range cases {
		tree := zzBuild(t, c.routes...)
		for _, fix := range []bool{true, false} {
			func() {
				defer func() {
					if recv := recover(); recv != nil {
