func fzPaths() []string {
	ps := []string{"/"}
	segs := []string{"a", "b", "ab", "ba", "x"}
	for _, s1 := range segs {
		ps = append(ps, "/"+s1)
	}
	for _, s1 := range segs {
		for _, s2 := range segs {
			ps = append(ps, "/"+s1+"/"+s2)
		}
	}
	for _, s1 := range segs {
		for _, s2 := range segs {
			for _, s3 := range segs {
				ps = append(ps, "/"+s1+"/"+s2+"/"+s3)
			}
		}
	}
	return ps
}

// expectedParams computes params for a pattern matching a path (simple matcher).
func expectedParams(pattern, path string) (map[string]string, bool) {
	pSegs := strings.Split(pattern[1:], "/")
	uSegs := strings.Split(path[1:], "/")
	res := map[string]string{}
	for i, ps := range pSegs {
		if i >= len(uSegs) {
			return nil, false
		}
		if strings.HasPrefix(ps, "*") {
			res[ps[1:]] = "/" + strings.Join(uSegs[i:], "/")
			return res, true
		}
		if strings.HasPrefix(ps, ":") {
			res[ps[1:]] = uSegs[i]
			continue
		}
		if ps != uSegs[i] {
			return nil, false
		}
	}
	if len(pSegs) != len(uSegs) {
		return nil, false
	}
	return res, true
}

func fzCheck(t *testing.T, routes []string, paths []string) {
	t.Helper()
	defer func() {
		if r := recover(); r != nil {
			// registration conflict: skip this route set
		}
	}()
	engine := New()
	var fullPath string
	var got Params
	engine.Use(func(c *Context) {
		fullPath = c.FullPath()
		got = append(Params{}, c.Params...)
		c.Next()
	})
	for _, r := range routes {
		engine.Handle("GET", r, func(c *Context) { c.String(200, "ok") })
	}
	for _, p := range paths {
		fullPath = ""
		got = nil
		w := httptest.NewRecorder()
		req, _ := http.NewRequest("GET", p, nil)
		engine.ServeHTTP(w, req)
		if fullPath == "" {
			continue // no match
		}
		if !strings.ContainsAny(fullPath, ":*") {
			if len(got) != 0 {
				t.Errorf("routes=%v path=%q matched static %q but got params %v", routes, p, fullPath, got)
			}
			continue
		}
		want, ok := expectedParams(fullPath, p)
		if !ok {
			t.Errorf("routes=%v path=%q matched %q which does not match path; params=%v", routes, p, fullPath, got)
			continue
		}
		if len(got) == 0 {
			t.Errorf("EMPTY PARAMS routes=%v path=%q matched=%q want=%v", routes, p, fullPath, want)
			continue
		}
		gotMap := map[string]string{}
		for _, pr := range got {
			gotMap[pr.Key] = pr.Value
		}
		if len(gotMap) != len(want) {
			t.Errorf("PARAM COUNT routes=%v path=%q matched=%q want=%v got=%v", routes, p, fullPath, want, got)
			continue
		}
		keys := make([]string, 0, len(want))
		for k := range want {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			if gotMap[k] != want[k] {
				t.Errorf("PARAM VALUE routes=%v path=%q matched=%q want=%v got=%v", routes, p, fullPath, want, got)
				break
			}
		}
	}
}

func TestZZFuzzPairs(t *testing.T) {
	pats := fzPatterns()
	paths := fzPaths()
	fmt.Printf("patterns=%d paths=%d\n", len(pats), len(paths))
	fails := 0
	for i := 0; i < len(pats); i++ {
		for j := i + 1; j < len(pats); j++ {
			fzCheck(t, []string{pats[i], pats[j]}, paths)
			fails++
			if t.Failed() && fails > 200 {
				return
			}
		}
	}
}
